                               "noticeText":  "[제18-1차 및 제18-2차 자유전공학부 D반 운영위원회 회의 공고]\n• 18-1차 일시: 2025.12.02.(화) 22:35 (온라인 ZOOM)\n  - 안건: 25학번 집행위원(기획국장 김채은, 홍보국장 이윤주) 사전 인준의 건 (만장일치 가결)\n• 18-2차 일시: 2025.12.04.(목) 22:32 (온라인 ZOOM)\n  - 안건:\n    1. 2, 3분기 결산 및 1, 4분기 예산안 검토의 건\n    2. 집행위원(복지국장 김동운, 기획국원 장여백, 복지국원 안희서, 홍보국원 박준원) 사전 인준의 건\n    3. 집행위원회 사업계획 및 정책 기본방향 사전 인준의 건\n    4. 2025 하반기 확대운영위원회 소집 요구의 건 (12/11 21:00)",
                               "thought":  "• 당선 직후(11/30 임기 시작) 바로 기말고사 시즌이 도래하기 때문에, 우리 공약이었던 간식행사·스터디윗D 개편안을 무리하게 12월에 급조하기보다 2025-2학기 기말 행사는 전대(17대) 방식을 유지해 안정적으로 치르고 2026학년도 1학기부터 개편안을 적용하기로 판단했습니다.\n• 또한 간식행사와 스터디윗D 공지가 같은 시간대에 올라가면 학우들의 주목도가 분산되므로, 12/5 오전에 간식행사, 오후에 스터디윗D를 분리 공지하도록 조정했습니다."
