                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2025.12.05 오후 12:18 쨌 학생회장 원준혁\n----------------------------------------\n[2025학년도 2학기 D반 기말고사 간식행사]\n\n안녕하세요, 제18대 D반 학생회 Duet 입니다.\n\n먼저 말씀 드리기에 앞서 저희 학생회장단에게 힘을 실어주신 모든 학우분들께 감사합니다.\n\n학우 여러분의 2학기 기말고사 응원을 위해 [D반 기말고사 간식행사]를 진행합니다! 많은 참여 부탁드립니다.\n\n저희의 임기 첫 행사인 2학기 기말고사 간식행사는 원활한 운영을 위해 기존 방식대로 진행되나, 2026년도 본 행사부터는 저희가 약속드린 개편안이 적용될 예정입니다. 더 나은 간식행사를 선보이기 위한 준비 과정이니 학우 여러분의 너그러운 양해 부탁 드립니다.\n\n구글폼: https://forms.gle/6VyuEVBzgi8162LP7\n\n🎁참여 방식 : 사전 신청 기간에 구글폼 선착순 신청 후, 반실에서 대면 수령\n🎁사전 신청 시간 : 25.12.8.(월) 17시~ (선착순 25명 마감)\n*17시 이전에 구글폼 제출 시 무효 처리되니, 꼭 17시 이후에 제출하시기 바랍니다.\n🎁실제 수령 시간 : 25.12.11.(목) 18시 30분 ~ 19시 30분\n🎁실제 수령 장소 : 구법학관 D반 반실\n🎁메뉴 : 이삭토스트 베이컨포테이토토스트 세트 (토스트, 감자튀김, 펩시제로라임 355ml) (9개) // 팡이네분식 옛날 떡볶이, 튀김 5개 + 펩시제로라임 500ml (8개) // 안암당 소프트 버터롤, 아이스 아메리카노(M), 에그 바닐라빈 타르트 (8개)\n\n❗학생회비 납부자만 신청 가능합니다.\n❗대면으로 본인이 수령함이 원칙입니다.\n❗명단 확정자(사전 신청자 가운데 선착순 25명)에 한하여 나눔합니다.\n❗메뉴 선택은 행사 당일 선착순으로  진행합니다.\n\n문의: 학생회장 원준혁\n제작: 홍보국장 이윤주\n\n??[공지 2] 2025.12.05 오후 6:04 쨌 학생회장 원준혁\n----------------------------------------\n[2025학년도 2학기 기말고사 스터디윗D 행사 안내]\n\n안녕하세요, 제18대 D반 학생회 Duet 입니다.\n\n벌써 연말이 되어 2025학년도 마지막 시험기간이 찾아왔습니다. 너무나 추워진 날씨에 공부하느라 지치셨을 학우 여러분들을 위해 스터디윗D 행사를 진행합니다! 열심히 공부하고 좋은 성적과 경품 받아가시길 바랍니다!\n\n이번 25-2 기말 스터디윗D는 원활한 운영을 위해 기존 방식대로 진행되나, 2026년도 본 행사부터는 저희가 약속드린 개편안이 적용될 예정입니다. 더 나은 행사를 선보이기 위한 준비 과정이니 학우 여러분의 너그러운 양해 부탁 드립니다.\n\n🗓️행사 기간 : 12/07 (일) - 12/16 (화)\n\n📚열품타 초대링크 : https://link.yeolpumta.com/P3R5cGU9Z3JvdXBJbnZpdGUmaWQ9NTgzNTE0OA==\n\n(비밀번호 : 2009)\n\n📚참여 방식\n\n1. 공유된 링크를 통해 \u0027열품타\u0027 앱 접속 후 닉네임을 이름+학번 뒤 3자리로 설정해주세요(ex. 우상준 144).\n\n2. 매일 공부를 시작할 때 타이머를 재생해주시고, 끝낼 때 타이머를 멈춰주세요.\n\n3. 🚨중요🚨잊지 말고 매일 \u0027하루 한 번 공부 인증\u0027 미션을 수행해주세요! 미수행 시 경품 지급 대상에서 제외될 수 있습니다.\n\n- * 타이머를 실수로 끄지 않은 경우를 배제하기 위해 최대 집중 시간이 5시간을 초과한 날은 집계에서 제외합니다 **\n\n📚경품 추첨\n\n경품 추첨은 10일의 기간 동안 \u00276일 이상 출석\u0027하고 \u0027총 공부시간 25시간 이상\u0027인 학우분들에 한하여 진행합니다.\n\n✅경품 목록\n\n- 쿠팡 기프트카드 1만원권 (1명)\n- 배민상품권 1만원권 (2명)\n- 메가커피 5천원권 (3명)\n\n문의: 기획국장 김채은, 학생회장 원준혁\n\n제작: 홍보국장 이윤주\n\n??[공지 3] 2025.12.05 오후 7:32 쨌 학생회장 원준혁\n----------------------------------------\n** 이번 진행되는 스터디윗D는 제18대 학생회 사업으로, 지난 17대에서 진행해왔던 링크와 다른 새로운 링크입니다. 기존 방에 가입하셨던 분들도 새로운 링크를 통해 들어와주시면 감사하겠습니다!\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[2025-2학기 D반 기말고사 스터디윗D 안내]\n안녕하세요, 자유전공학부 D반 제18대 학생회 Duet 기획국입니다!\nD반과 함께 기말고사를 불태울 \u003c기말고사 스터디윗D\u003e를 진행합니다🔥\n\n📅 일시: 12/07(일) ~ 12/16(화) (10일간)\n📌 참여 방법:\n1. 열품타 접속 후 D반 그룹 가입하기 (참여코드 및 링크는 공지방 참고)\n2. 매일 공부 시작 전후로 타이머 체크 \u0026 공부 인증 미션 수행하기!\n   (*최대 집중 시간이 5시간을 초과한 날은 공부시간 집계에서 제외됩니다!)\n3. 조건(10일 중 6일 이상 출석, 총 공부시간 25시간 이상) 만족한 학우들 대상으로 추첨을 통해 경품 지급!\n\n🎁 경품 안내:\n• 쿠팡 기프트카드 1만원권 (1명)\n• 배달의민족 상품권 1만원권 (2명)\n• 메가커피 모바일 금액권 5천원권 (3명)\n(추첨 및 발표: 12/18~19)",
