                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 2건)]\n\n??[공지 1] 2025.12.07 오후 8:02 쨌 학생회장 원준혁\n----------------------------------------\n[2025년 하반기 D반 확대운영위원회 회의 소집 공고]\n\n안녕하세요, 학생회장입니다. D반 학생회칙에 따라 2학기 종강 전 2025 하반기 확대운영위원회를 개의하고자 합니다.\n\n📍12월 11(목) 21시\n📍온라인 회의 (Zoom)\n\n안건지를 함께 보내드리니 확인 부탁드립니다. 온라인 회의 링크는 추후 공지 예정입니다. 또한, 자유전공학부 네이버 카페와 D반 인스타그램 계정으로도 관련 사항 공지 될 예정이니 참고하시면 되겠습니다. D반 제18대 학생회의 전반적인 사업 계획과 정책의 기본방향에 대한 소개 및 의결이 진행될 예정이니 큰 관심 부탁드리겠습니다.\n\n시험 기간 공부하시느라 바쁘시겠지만 앞으로 활동할 D반 학생회를 소개하는 자리인 만큼 시간 내셔서 회의 참여해주시면 감사하겠습니다.\n\n자유전공학부 D반 재학생 학우분이라면 모두 의결권이 있으며, 회의 소요 시간이 길지 않을테니 많은 참여 바랍니다!\n\n| 문의: 학생회장 원준혁\n\n??[공지 2] 2025.12.07 오후 8:03 쨌 학생회장 원준혁\n----------------------------------------\n파일: 2025 하반기 D반 확대운영위원회 회의 안건지.pdf\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[2025-2학기 D반 기말고사 스터디윗D 안내]\n안녕하세요, 자유전공학부 D반 제18대 학생회 Duet 기획국입니다!\nD반과 함께 기말고사를 불태울 \u003c기말고사 스터디윗D\u003e를 진행합니다🔥\n\n📅 일시: 12/07(일) ~ 12/16(화) (10일간)\n📌 참여 방법:\n1. 열품타 접속 후 D반 그룹 가입하기 (참여코드 및 링크는 공지방 참고)\n2. 매일 공부 시작 전후로 타이머 체크 \u0026 공부 인증 미션 수행하기!\n   (*최대 집중 시간이 5시간을 초과한 날은 공부시간 집계에서 제외됩니다!)\n3. 조건(10일 중 6일 이상 출석, 총 공부시간 25시간 이상) 만족한 학우들 대상으로 추첨을 통해 경품 지급!\n\n🎁 경품 안내:\n• 쿠팡 기프트카드 1만원권 (1명)\n• 배달의민족 상품권 1만원권 (2명)\n• 메가커피 모바일 금액권 5천원권 (3명)\n(추첨 및 발표: 12/18~19)",
                               "thought":  "• 열품타 타이머를 켜놓고 잠드는 허수 시간을 막기 위해 \u00271일 최대 집중시간 5시간 초과일은 집계에서 제외\u0027하는 규칙을 명확히 고지했습니다.\n• 이 회차까지는 기존 추첨제(총 6명 시상, 45,000원)로 운영했고, 이후 1월 기획국 회의와 4월 국장단회의를 거치며 \u0027기준 달성자 전원 소정의 상품 + Best 고액 경품 추첨\u0027 혼합제로 발전시켰습니다."
