                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2025.12.09 오전 11:48 쨌 학생회장 원준혁\n----------------------------------------\n간식행사 아직 2자리 남아있습니다!\n\n??[공지 2] 2025.12.09 오후 3:25 쨌 부학생회장 우상준\n----------------------------------------\n[돕바 배부 안내]\n\n안녕하세요, D반 부학생회장입니다. 오리털 돕바가 도착하여 공지드립니다. 배부는 구법학관 D반 반실에서 12/11(목)까지 진행할 예정입니다. 솜털 돕바의 경우 아직 도착하지 않아, 추후 다시 공지 드리겠습니다.\n\n🗓️수령 일자: 12/9(화) 15:30 ~ 12/11(목) 17:30\n🗓️수령 가능 시간:\n12/9 (화): 15:30~21:00\n12/10 (수): 9:00~12:00, 13:30~21:00\n12/11 (목): 9:00~10:00, 11:00~13:00, 13:30~17:30\n\n(시험 기간과 겹쳐 집행위원이 모든 시간대에 상주하기 어려운 관계로, 배부 가능 시간이 다소 불규칙한 점 양해 부탁드립니다.)\n\n🚨수령은 오직 ‘수령 가능 시간’에 반실에 있는 ‘집행위원’을 통해서만 가능합니다.\n🚨학생회 집행위원의 허가 없이 무단으로 가져가실 수 없습니다. \n🚨하자 여부 확인을 위해, 수령하면서 옷의 상태를 확인해주시기 바랍니다. \n🚨옷 상태 확인 후 배부 명단에 서명을 꼭 해주시기 바랍니다. 서명하지 않으실 경우 다시 반실에 오셔서 직접 서명하셔야 합니다. \n🚨12/11까지 배부시간에 방문이 어렵거나 대리 수령을 원하시는 분들은 개인톡으로 연락 부탁드립니다. \n\n(금일부터 바로 배부가 시작되오니, 공지 내용을 확인하시어 수령해 주시길 부탁드립니다. 시험 기간이라 촉박하게 진행되는 점 다시 한 번 너른 양해를 구합니다.)\n\n??[공지 3] 2025.12.09 오후 5:59 쨌 부학생회장 우상준\n----------------------------------------\n[2025학년도 2학기 기말고사 간식행사 명단 확정]\n\n안녕하세요, Duet입니다. \n\n25-2 기말고사 간식행사 확정 명단 보내드립니다. 간식행사 확정 명단 내 본인의 성함과 학번 확인 부탁드립니다! 간식행사는 11일 목요일 18시 30분부터 1시간 동안 반실에서 배부할 예정입니다. 메뉴 선택은 당일 선착순으로 진행됩니다. 감사합니다.\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n(((( 12/9 화 저녁 ~ 12/10 수 사이 )))\n명단 확정 및 공지",
