                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 4건)]\n\n??[공지 1] 2025.12.16 오후 2:31 쨌 학생회장 원준혁\n----------------------------------------\n[2025년 하반기 확대운영위원회 회의 결과 공고]\n\n회의록 및 세부사항은 자유전공학부 학생회 네이버 카페에서 열람하실 수 있습니다.\n\n| 문의: D반 학생회장 원준혁\n| 제작: 홍보국원 박준원\n\n??[공지 2] 2025.12.16 오후 2:52 쨌 학생회장 원준혁\n----------------------------------------\n[돕바 2차 공구 가수요조사]\n\n안녕하세요, 학생회장입니다. \n돕바 추가 공구 요청이 들어와 다른 반 학생회장들과 상의한 결과, 수요가 있는 것으로 확인되어 실수요조사 전 인원을 파악하고자 합니다. \n\n**공구를 원하시는 분은 해당 게시글에 ✅️표시 부탁드립니다!**\n\n마감 기한: 12월 18일(목) 23시 59분까지\n\n* 가수요조사 인원이 저조할 경우 공구가 취소될 수 있습니다.\n* 2차 공구 시 인원이 상대적으로 적어, 기존보다 약 4000원 정도 높은 가격으로 책정될 예정입니다.\n* 주문 시점 기준 1개월 전후로 도착 예정입니다.\n\n??[공지 3] 2025.12.16 오후 2:54 쨌 학생회장 원준혁\n----------------------------------------\n* 사장님께서 가격 약 99,000원 정도로 말씀하셨습니다!\n\n??[공지 4] 2025.12.16 오후 6:02 쨌 학생회장 원준혁\n----------------------------------------\n[25-2 기말고사 스터디윗D 행사 마감 안내]\n\n스터디윗D 행사 오늘(12/16)까지입니다.\n\n마지막까지 공부 인증 잊지 말고 부탁드립니다. 감사합니다!\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[2025년 하반기 자유전공학부 D반 확대운영위원회 결과 공고]\n• 일시: 2025.12.11.(목) 21:05 ~ 21:46 (Google Meet, 총 17명 출석)\n• 의결 결과:\n  1. 학생회 운영 및 사업 전반에 관한 건 — 가결 (출석 16, 찬성 14, 의결권없음 2)\n  2. 집행위원회 사업계획과 정책의 기본방향 인준의 건 — 가결 (출석 16, 찬성 14, 의결권없음 2)\n  3. 집행위원 6인(김채은, 장여백, 김동운, 안희서, 이윤주, 박준원) 사후 인준의 건 — 가결 (출석 16, 찬성 9, 기권 1, 의결권없음 6)\n  4. 2025년 2·3분기 결산 및 2025년 4분기·2026년 1분기 예산안 승인의 건 — 가결",
