                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 2건)]\n\n??[공지 1] 2026.01.19 오후 3:49 쨌 학생회장 원준혁\n----------------------------------------\n[확대운영위원회 일정 투표 안내]\n\n안녕하세요, 자유전공학부 D반 제18대 학생회 Duet 입니다.\n\n제18-4차 D반 운영위원회 회의를 통해 발의 예정인 회칙 개정안 심의 및 학생총회 소집, 국서 명칭 변경 사후 인준을 위한 확대운영위원회를 소집하고자 합니다. \n\n이번 회의는 회칙 개정안 심의라는 중요한 안건을 다루는 만큼, D반 구성원 여러분의 적극적인 참여가 필요합니다!\n\n📌 확대운영위원회 개요\n일시: 아래 투표를 통해 결정 (가능한 모든 날짜에 투표 부탁드립니다)\n시간: 12:00 ~ 13:00 또는 18:00 ~ 19:00 사이 (약 30분 내외로 진행 예정)\n장소: D반 반실 (온라인 병행)\n\n📌 참고 사항\n회의 결과, 학생총회 소집이 결정될 경우 2월 첫째 주 수요일(2/4), 목요일(2/5), 금요일(2/6) 중에 개의 예정이며, 구체적인 일자는 추후 별도 투표를 통해 확정할 예정입니다.\n\n학생사회의 민주성과 지속성을 함께 만들어갈 수 있도록 많은 관심과 참여 부탁드립니다.\n\n감사합니다.\n\n| 문의: D반 학생회장 원준혁\n\n??[공지 2] 2026.01.19 오후 3:51 쨌 학생회장 원준혁\n----------------------------------------\n톡게시판 \u0027투표\u0027: 확운위 날짜\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 5차 학운위 임시회의\n• 일시: 2026.01.19\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
