                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2026.01.20 오후 1:11 쨌 학생회장 원준혁\n----------------------------------------\n[돕바 2차 공구 배부 안내]\n\n안녕하세요, D반 학생회장입니다. 2차 공구한 돕바가 도착하여 공지드립니다. 배부는 구법학관 D반 반실에서 1/30(금)까지 진행할 예정입니다. \n\n🗓️수령 일자: 1/20(화) ~ 1/23(금) / 1/26(월) ~ 1/30(금)\n\n❗중요❗\n방학 중인 관계로 집행위원이 반실에 상시 대기할 수 없어 배부 일시 확정을 위한 방문 가능 시간을 수합하고자 합니다.\n\u0027내일(1/21(수))\u0027까지 학생회장 개인톡으로 연락 부탁드립니다. (ex. 21일 14시~18시, 22일 15시~20시, 23일 14~20시 수령 가능합니다.)\n\n🚨수령은 오직 ‘집행위원’을 통해서만 가능합니다.\n🚨학생회 집행위원의 허가 없이 무단으로 가져가실 수 없습니다. \n🚨하자 여부 확인을 위해, 수령하면서 옷의 상태를 확인해주시기 바랍니다. \n🚨옷 상태 확인 후 배부 명단에 서명을 꼭 해주시기 바랍니다. 서명하지 않으실 경우 다시 반실에 오셔서 직접 서명하셔야 합니다. \n🚨1/30(금)까지 배부시간에 방문이 어렵거나 대리 수령을 원하시는 분들은 개인톡으로 연락 부탁드립니다. \n\n*금일부터 바로 배부가 시작되오니, \n공지 내용을 확인하시어 방문 가능 날짜와 시간 연락 부탁드립니다!\n\n??[공지 2] 2026.01.20 오후 5:30 쨌 학생회장 원준혁\n----------------------------------------\n톡게시판 \u0027투표 종료 전 알림\u0027: 확운위 날짜\n\n??[공지 3] 2026.01.20 오후 6:00 쨌 학생회장 원준혁\n----------------------------------------\n톡게시판 \u0027투표 종료\u0027: 확운위 날짜\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 제18-4차 반운위\n• 일시: 2026.01.20\n• 담당 국서: 학생회장단, 반 운영위원회\n• 진행 상태: 완료",
