                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2026.01.30 오후 2:29 쨌 학생회장 원준혁\n----------------------------------------\n[제18-1차 확대운영위원회 임시회의 결과 공고]\n\n회의록 및 세부사항은 자유전공학부 학생회 네이버 카페에서 열람하실 수 있습니다.\n\n| 문의: D반 학생회장 원준혁\n| 제작: 홍보국원 박준원\n\n??[공지 2] 2026.01.30 오후 2:35 쨌 학생회장 원준혁\n----------------------------------------\n[1월 집행위원회 월간보고]\n\n안녕하세요, 자유전공학부 D반 제18대 학생회 Duet입니다.\n\n다음과 같이 1월 집행위원회 업무 보고를 안내드립니다. 자세한 사항은 카드뉴스를 참고하시길 바랍니다.\n\n감사합니다.\n\n| 제작: 홍보국장 이윤주\n| 문의: 학생회장 원준혁\n\n??[공지 3] 2026.01.30 오후 7:13 쨌 학생회장 원준혁\n----------------------------------------\n[제18-1차 D반 학생총회 소집 공고]\n\n안녕하세요, 학생회장입니다. 회칙 개정안 의결을 위해 학생총회 회의를 소집하고자 합니다.\n\n📍회의 일시: 2월 4일(수) 18시\n📍회의 장소: 법학관구관 104호 및 온라인 회의실 (Google Meet)\n\n온라인 회의실 링크는 추후 공지 예정입니다. 자유전공학부 D반 재학생 학우분이라면 모두 의결권이 있으며, 회의 소요 시간이 길지 않을테니 많은 관심과 참여 부탁드립니다!\n\n| 문의: 학생회장 원준혁\n| 제작: 홍보국원 박준원\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[1월 월간보고 (2026.01.30)]\n• 담당 국서: 학생회장단, 기획국, 복지국, 홍보국\n• 진행 상태: 완료\n• 해당 월의 집행위원회 국서별(학생회장단·기획국·복지국·홍보국) 활동 내역 카드뉴스 슬라이드(6장)를 상단 이미지 뷰어 및 하단 월간보고 표에서 확인하실 수 있습니다.",
