                               "thought":  "• 해가 바뀌고 3월 신입생 대표 선출 전까지 2학년이 된 전년도 대표가 \u0027신입생 대표\u0027 직을 유지하는 회칙상 모순(제65조 제1항 vs 제4조 제3항)을 해결하기 위해 개정을 추진했습니다.\n• 이때 가장 중요하게 생각한 두 가지는 ① 현직 신입생 대표(김도현)의 임기를 사후적으로 단축하는 \u0027소급 적용\u0027은 민주적 정당성에 어긋나므로 반드시 부칙 경과조치로 기존 임기를 보장할 것, ② 방학 중 학생총회 정족수(24명) 미달 사태를 막기 위해 사전에 날짜 수요조사를 돌리고 대면+비대면 병행으로 열람·참여 장벽을 낮춘 것입니다."
