                               "noticeText":  "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2026.02.05 오후 7:01)\n----------------------------------------\n[제18-1차 학생총회 회의 결과 공고]\n\n회의록 및 세부사항은 자유전공학부 학생회 네이버 카페에서 열람하실 수 있습니다.\n\n| 문의: D반 학생회장 원준혁\n| 제작: 홍보국원 박준원\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n냉장고 관련 수칙\n금방 처리하지 않을 것으로 예상되는 식품은 보관 대신 버리기\n특히 상하기 쉬운 과일, 우유 등은 가급적 보관하지 말고 처리하기\n보관이 필요하다면, 냉장고 위에 있는 포스트잇에 소유자 이름, 보관 날짜 써서 식품에 붙여놓기\n위생 및 개인 물품 관련 수칙\n책상은 모두가 이용하는 데 불편함이 없도록, 책상 공간을 차지하는 물품은 사용 후 가져가기\n기본적인 반실 이용 에티켓을 지키기. 쓰레기는 쓰레기통에 잘 버리고, 음식물을 흘렸다면 깨끗이 닦기\n담요는 사용 시 떨어뜨리지 않도록 주의하고, 사용 후 떨어지지 않게 잘 올려두기\n반실 공용 물품 사용 후 반드시 원위치에 두기.\n충전기는 반실 밖으로 가지고 가지 말기 (대여 대상이 아닙니다)\n모두가 함께 쓰는 공간인만큼 이용수칙을 지켜주시길 바랍니다.\n문의는 자유전공학부 D반 공식 인스타그램(@kusis_d) DM이나 링크트리의 학생회 오픈채팅방을 이용해주세요.",
                               "thought":  "• 노션(Notion) 캘린더 데이터베이스에서 동기화된 제18대 학생회 Duet 공식 일정입니다. 관리자 모드에서 [✏️ 코멘트/공지 편집]을 켜면 이 일정에 대한 세부 코멘트를 자유롭게 추가하실 수 있습니다."
