                               "noticeText":  "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2026.02.23 오후 6:44)\n----------------------------------------\n\u003c🎉2026 D반 개강파티 가수요조사🎉\u003e\n\n안녕하세요! D반에 오신 여러분, 환영합니다! 이제 얼마 남지 않은 개강을 맞이하여 개강파티를 하려고 합니다. 대략적인 인원을 확인하고자 가수요조사를 실시합니다! 이번 개강파티는 전학번이 참여할 수 있도록 하였습니다.\n같은 반 학우분들을 만날 좋은 기회이기도 하니 많은 참여 부탁드립니다! 일시와 장소는 다음과 같습니다. 아래 구글폼을 통해 신청해주세요.\n\n📎일시 : 3월 3일 19시~22시\n📎장소 : 안암아줌마치킨\n📎구글폼: https://forms.gle/xWHPY7oFM7rGwu5K8\n📎기한: 2/25(목) 23:59까지\n\n*본 공지는 가수요조사로서 인원파악을 위한 용도로, 추후 실수요조사에 참여하셔야 참여가 확정이라는 점 안내해드립니다.\n\n문의: D반 학생회장 원준혁\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[25~26학번 D반 뻔선뻔후 매칭 및 친해져도 Dㅐ? 안내]\n• 뻔라인 매칭 원칙:\n  1. 25학번 대상 사전 설문조사 실시 (뻔후 희망 여부, 외국인 배정 선호도, 2명 이상 추가 입양 가능 여부 조사)\n  2. 학번 끝 3자리가 같은 25·26학번을 \u0027친뻔\u0027으로 우선 매칭\n  3. 친뻔선이 없거나(200번대 학번 등) 미응답인 경우, 다수 배정을 자원한 25학번 선배(\u0027입양명단\u0027)에게 \u0027입양\u0027 매칭 및 새터 참여 여부(O/X) 표기 배포\n• 2026 친해져도 Dㅐ?: 2/23(월) 공지 업로드, 25학번 2명 + 26학번 2명(4인 1조) 매칭 신청 개시",
                               "thought":  "• 매년 뻔라인 매칭 때 연락 두절인 선배나 학번 끝자리가 안 맞는 신입생(특히 외국인·추가합격 학우)이 소외되는 문제가 있었습니다. 그래서 25학번에게 미리 \u0027외국인 신입생 배정 가능 여부\u0027와 \u0027뻔후 2~3명 입양 가능 여부\u0027를 설문으로 받아 매칭표를 짰고, 새터 참여 여부까지 표기해 주어 새터 현장에서 선배들이 자기 뻔후를 바로 챙길 수 있게 했습니다."
