                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2026.02.25 오후 4:17 쨌 학생회장 원준혁\n----------------------------------------\n[새내기 총mt 준비위원 모집]\n\n자유전공학부 학우 여러분 안녕하세요, 다가오는 3월 14일 새내기 총 mt를 함께 준비할 분들을 모집하고자 합니다! 26학번 새내기분들의 첫번째 mt인 만큼 많은 도움 주시면 감사하겠습니다🥹🥹\n\n✔️ 지원 대상: 25학번 이상 학우\n✔️ 모집 인원: 8명(학운위 미포함 8명 내외)\n✔️ 업무\n💫 엠준위 - 레크레이션 프로그램 구성, 현장 관리, 장보기, 고기 굽기 등 - 8명 내외\n💫 학운위(각 반 회장단 1명 이상)- 반 인원 인솔, 안전 관리\n💫 회장단 - 장소 예약, 예산안 작성, 출입금 관리 등\n✔️ 신청 방법\n부학생회장 신예빈에게 개인톡으로 이름/반을 적어서 2월 25일(수) 18:00까지 제출\n- 예) 신예빈/A\n✔️ 장소: 가평 대성리 이오스펜션 그랜드홀\nhttps://naver.me/FcgAWfD4\n\n🌟많은 참여를 부탁드립니다~!!🌟\n문의: 학부 부학생회장 신예빈\n\n??[공지 2] 2026.02.25 오후 4:18 쨌 학생회장 원준혁\n----------------------------------------\n학부 학생회 요청으로 전달합니다!\n\n??[공지 3] 2026.02.25 오후 5:04 쨌 학생회장 원준혁\n----------------------------------------\n안녕하세요. 학생회장입니다.\n\n고려대학교의 뜨거운 응원 문화를 경험할 수 있는 두 가지 큰 행사가 다가옵니다. 원활한 행사 기획을 위해 가수요조사를 진행하려합니다. \n\n📎응원 OT (3/17 화, 화정체육관) : 고려대학교의 응원가와 동작을 고려대학교 응원단에게 배우는 행사\n📎합동응원전 (3/20 금, 녹지운동장) : 응원OT에서 배운 응원가와 동작을 바탕으로 연세대학교 학우와 응원을 함께하는 행사\n\n❗️가수요조사 구글 폼: https://forms.gle/LSKsB6wYyABGCMTz6\n❗️기간: ~3/4 23:59\n\n* 본 공지는 가수요조사로서 인원파악을 위한 용도로, 추후 실수요조사에 참여하셔야 참여가 확정이라는 점 안내해드립니다.\n\n| 문의: 학생회장 원준혁\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 26집행위원 면접 질문 국장방 논의\n• 일시: 2026.02.25\n• 담당 국서: 학생회장단, 기획국, 복지국, 홍보국\n• 진행 상태: 완료",
