                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 2건)]\n\n??[공지 1] 2026.02.28 오후 2:15 쨌 학생회장 원준혁\n----------------------------------------\n[과잠(크잠) 공구 실수요조사 연장 안내]\n오늘 2/28 23:59까지로 과잠 실수요조사 기간이 연장되었으니 구매를 희망하시는 분들은 신청 부탁드립니다.\n\n??[공지 2] 2026.02.28 오후 2:38 쨌 학생회장 원준혁\n----------------------------------------\n\u003c🎉D반 개강파티 실수요조사🎉\u003e\n\n안녕하세요! D반 제18대 학생회 Duet입니다. 이제 얼마 남지 않은 1학기 개강을 맞이하여 개강파티 실수요조사를 진행하고자 합니다. 같은 반 학우들을 만나 친해질 수 있는 좋은 기회이니, 관심 있는 분들께서는 신청 기간 내에 폼을 제출해주시고 예약금 입금을 완료해주시길 바랍니다. 많은 관심 부탁드립니다!\n\n📍일시 : 3월 3일 (화) 19:00\n📍장소 : 안암아줌마치킨\n📎 예약금: 10,000원\n📎 입금 계좌: [계좌번호 마스킹] 토스뱅크 우상준\n📎 입금명: 학번 + 성명 (예: 25우상준)\n📎구글폼: https://forms.gle/Y2HMmcQ6oWAoYn4W8 \n📎기한: 3/2(월) 23:59까지\n\n‼️ 이전에 가수요조사와는 별개이니, 가수요조사에 참여하셨더라도 이번 실수요조사 구글폼 제출과 예약금 입금 모두 완료해주시길 바랍니다! \n‼️ 폼 작성과 더불어 예약금 입금이 완료되어야 참석으로 간주되오니 잊지 말고 입금하시길 바랍니다. 행사 전날 혹은 당일 취소 시 예약금은 환불이 어려운 점 양해 부탁드립니다. 곧 뵙겠습니다! \n\n문의: D반 학생회장 원준혁 010-****-****\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 총MT 숙소 예약\n• 일시: 2026.02.28\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
