                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2026.03.02 오후 12:39 쨌 부학생회장 우상준\n----------------------------------------\n[개강파티 신청 리마인드 공지]\n\n개강파티 실수요조사 금일 23:59까지입니다! 기한 참고하시어, 잊지말고 예약금 입금과 구글폼 함께 제출해주시길 바랍니다. 많은 관심 부탁드립니다. 감사합니다!\n\n??[공지 2] 2026.03.02 오후 5:17 쨌 학생회장 원준혁\n----------------------------------------\n[D반 반실 이용수칙 안내]\n\n안녕하세요, Duet 복지국입니다.\n\nD반 반실 이용 시 지켜야 할 수칙에 관하여 안내드립니다.\n이용수칙의 자세한 내용은 사진을 참고 부탁드리며, 반실의 각 공간에 부착된 이용수칙을 통해서도 확인하실 수 있습니다.\n\n반실은 D반 학우 모두가 함께 사용하는 공간이므로, 모두에게 쾌적하고 편안한 반실이 될 수 있도록 이용수칙을 잘 지켜주시길 부탁드립니다.\n\n감사합니다.\n\nㅣ문의: 학생회장 원준혁, 복지국장 김동운\nㅣ제작: 홍보국장 이윤주\n\n??[공지 3] 2026.03.02 오후 5:19 쨌 학생회장 원준혁\n----------------------------------------\n[D반 반실 한 눈에 알아보기]\n\n안녕하세요, Duet 복지국입니다.\n\n26학번 새내기 학우분들과 새롭게 시작하는 한 해를 위하여 복지국에서 반실을 새롭게 단장하였습니다! 자세한 사항은 카드뉴스 참고 바랍니다.\n\n쾌적하고 편안한 반실 환경은 모두의 배려와 작은 실천에서 시작됩니다. D반 모두가 함께 사용하는 공간인 만큼, 자신의 공간처럼 아껴주시고 정리 정돈에 신경 써주시길 바랍니다!\n\n앞으로도 D반 학우분들의 편안한 대학 생활을 위해 더욱 노력하는 복지국이 되겠습니다.\n\n감사합니다.\n\nㅣ문의: 학생회장 원준혁, 복지국장 김동운\nㅣ제작: 홍보국장 이윤주\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[새 단장한 D반 반실 한눈에 알아보기 \u0026 이용수칙 안내]\n안녕하세요, 자유전공학부 D반 제18대 학생회 Duet 복지국입니다!\n2026년 1학기 개강을 맞아 법학관 구관 104호 D반 반실이 새롭게 단장했습니다✨\n\n🔌 1. 비치 물품 전면 교체\n• 핸드폰 충전기(아이폰 8핀, C타입) 및 노트북 충전기(65W 초고속) 구비 (전용 바구니 분리 보관)\n• 책상 근처 3m 멀티탭 3개 고정, 담요 2개, 물티슈, 대형 아크릴 거울 비치\n\n☂️ 2. 우산 \u0026 보조배터리 대여 사업 신설\n• 비 오는 날 우산꽂이의 장우산(4개), 배터리 부족할 때 일체형 보조배터리(2개) 대여 가능!\n• 대여 방법: 반실 내 대여 명단 작성 + 복지국장(010-****-****)에게 문자 연락 후 대여 (주말 제외 이틀 뒤까지 반납 필수)\n\n📸 3. 즐길거리 \u0026 추억 공간 \u0026 홍보게시판\n• 다양한 보드게임 구비 / 벽면 마스킹테이프 \u0027추억 공간\u0027에 인생네컷 사진을 자유롭게 붙여주세요!\n• 소화전 위 화이트보드 홍보게시판에 밴드 공연, 동아리, 소모임을 홍보해 보세요 (부착 전 학생회장·복지국장 문의)\n\n❄️ 4. 냉장고 및 기본 이용수칙\n• 냉장고 음식 보관 시 [이름 + 보관 날짜] 필수 기재! (2주 간격 정기 청소 시 미기재 또는 4주 경과 음식물은 통보 없이 폐기됩니다)",
                               "thought":  "• 학우들이 학부 학생회실보다 구법학관 1층 D반 반실을 훨씬 자주 들른다는 점에 착안해 우산·보조배터리 대여 사업을 신설했습니다.\n• 보증금을 받을지 고민했으나 학생회비로 산 물품에 보증금을 또 걷는 건 맞지 않다고 판단해 \u0027명부 수기 작성 + 복지국장 문자 연락\u0027으로 운영했습니다. 초기에는 학우들이 문자 연락을 깜빡하는 경우가 있어 2차 국장단회의(3/7) 피드백을 거쳐 대여 안내문 글자 크기와 색상을 눈에 띄게 키웠습니다."
