                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2026.03.02 오후 12:39 쨌 부학생회장 우상준\n----------------------------------------\n[개강파티 신청 리마인드 공지]\n\n개강파티 실수요조사 금일 23:59까지입니다! 기한 참고하시어, 잊지말고 예약금 입금과 구글폼 함께 제출해주시길 바랍니다. 많은 관심 부탁드립니다. 감사합니다!\n\n??[공지 2] 2026.03.02 오후 5:17 쨌 학생회장 원준혁\n----------------------------------------\n[D반 반실 이용수칙 안내]\n\n안녕하세요, Duet 복지국입니다.\n\nD반 반실 이용 시 지켜야 할 수칙에 관하여 안내드립니다.\n이용수칙의 자세한 내용은 사진을 참고 부탁드리며, 반실의 각 공간에 부착된 이용수칙을 통해서도 확인하실 수 있습니다.\n\n반실은 D반 학우 모두가 함께 사용하는 공간이므로, 모두에게 쾌적하고 편안한 반실이 될 수 있도록 이용수칙을 잘 지켜주시길 부탁드립니다.\n\n감사합니다.\n\nㅣ문의: 학생회장 원준혁, 복지국장 김동운\nㅣ제작: 홍보국장 이윤주\n\n??[공지 3] 2026.03.02 오후 5:19 쨌 학생회장 원준혁\n----------------------------------------\n[D반 반실 한 눈에 알아보기]\n\n안녕하세요, Duet 복지국입니다.\n\n26학번 새내기 학우분들과 새롭게 시작하는 한 해를 위하여 복지국에서 반실을 새롭게 단장하였습니다! 자세한 사항은 카드뉴스 참고 바랍니다.\n\n쾌적하고 편안한 반실 환경은 모두의 배려와 작은 실천에서 시작됩니다. D반 모두가 함께 사용하는 공간인 만큼, 자신의 공간처럼 아껴주시고 정리 정돈에 신경 써주시길 바랍니다!\n\n앞으로도 D반 학우분들의 편안한 대학 생활을 위해 더욱 노력하는 복지국이 되겠습니다.\n\n감사합니다.\n\nㅣ문의: 학생회장 원준혁, 복지국장 김동운\nㅣ제작: 홍보국장 이윤주\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[개강 공지]\n안녕하세요, D반 학생회장입니다. 드디어 개강이 하루 앞으로 다가왔습니다! 여러분들의 재미있는 새 학기를 위해 안내드릴 내용이 몇 가지 있으니 참고 부탁드립니다.\nD반 카카오톡 오픈채팅방\n이 오픈채팅방에서는 학생회 사업에 대한 전반적인 제안 및 질의 뿐만 아니라, 학생회 사업 이외의 모든 내용 다 가능합니다! 익명으로 전달하고 싶은 내용이 있다면 이 오픈채팅방으로 알려주세요. 추가적으로 하단에 학생회장과 부학생회장의 연락처를 하단에 남겨두겠습니다. 참고하시어 비상시/ 문의사항 발생시 연락주세요.\n🖇️ https://open.kakao.com/o/sqU45O4h\n📞 원준혁(뻔대) 010-****-****\n📞 우상준(부뻔대) 010-****-****\n출입신청 안내\n추후 전체 공지방에 공지가 될 내용으로 알고 있는데, 그 시점에 신청 해주시면 될 듯 합니다. D반 반실(104호)와 코웍스(구법학관 2층)까지 출입신청 해주시면 편리한 학교생활이 될 수 있을 겁니다! 출입신청은 고려대학교 홈페이지 KUPID에서 할 수 있고 자세한 내용은 이후 전체 공지방을 참고해주시면 감사하겠습니다 (지금 하지 않아도 문제는 없습니다).\n반실 안내\n구법학관에 들어와서 오른쪽으로 가면 차례대로 ABCD반 반실이 있습니다. 반실은 현재 비밀번호가 없으니 그냥 열고 들어오셔도 됩니다. 반실은 D반의 모든 구성원이 이용 가능하니 편하게 들어와도 됩니다! 우리 모두가 쓰는 공간이기에 항상 청결을 유지해주시고 귀중품은 각자 챙기셔야 합니다. 함께 첨부된 반실 이용 수칙을 정독해주시고 꼭꼭 준수해주시길 바랍니다.\n즐거운 학교생활 하시길 바라며 다시 한 번 D반에 오신 것을 환영합니다!",
                               "thought":  "• 개강 하루 전날 신입생과 재학생 모두에게 ① 익명 건의가 가능한 카카오톡 오픈채팅방 링크, ② 학생회장단 비상 연락처, ③ KUPID 구법학관 104호(D반 반실) 및 코웍스 출입신청 방법, ④ 반실 이용수칙을 한 번에 정리해 공지하면 학기 초 혼선을 크게 줄일 수 있습니다."
