                               "noticeText":  "[자유전공학부 D반 제18대 학생회 Duet 집행위원 모집 공고]\n안녕하세요, 자유전공학부 D반 제18대 학생회 Duet입니다!\nD반을 함께 이끌어갈 신입 집행위원을 모집합니다🎶\n\n📌 모집 국서:\n• 기획국: 스터디윗D, 친해져도 Dㅐ?, 총MT, 교류반 행사 등 친목·학업 행사 기획\n• 복지국: 반실 환경 조성 및 정기 청소, 우산·보조배터리 대여 사업, 시험기간 간식행사 운영\n• 홍보국: 인스타그램 계정(@kusis_d) 운영, 월간보고 및 사업 카드뉴스 제작, 피드백 수합\n\n📅 정기모집(26학번): 3/3(화)~3/6(금) 접수 → 3/9~11 면접 → 3/12 발표\n📅 추가모집(25·26학번 전체): 3/14(토)~3/19(목) 접수 → 3/22(일) 면접 및 발표\n🔗 지원 방법: 공지방 및 인스타 프로필 구글폼 작성 (문의: 학생회장 원준혁 010-****-****)",
