                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2026.03.03 오후 1:02 쨌 학생회장 원준혁\n----------------------------------------\n[반실 사진 부착 안내]\n\n안녕하세요, Duet 복지국입니다.\n\n반실 내 인생네컷 등의 사진 부착과 관련하여 안내드립니다.\n첨부한 사진에 노란색으로 표시된 범위 내의 벽면에만 부착 가능하며, 해당 공간 외에 사진을 부착할 경우 별다른 고지 없이 제거될 수 있다는 점 말씀드립니다.\n\n매 학기가 끝난 후 해당 공간에 부착된 사진은 수납장에 있는 앨범에 옯겨 놓을 예정이니 참고 부탁드립니다.\n\n깨끗하고 정돈된 반실을 위하여 해당 공지글의 내용을 꼭 지켜주시면 감사하겠습니다.\n\nㅣ문의: 복지국장 김동운\n\n??[공지 2] 2026.03.03 오후 4:37 쨌 학생회장 원준혁\n----------------------------------------\n주문서 정리본입니다. 수정사항 있으신 분은 오늘 저녁 20:00까지 보내주시길 바랍니다!\n\n??[공지 3] 2026.03.03 오후 6:06 쨌 학생회장 원준혁\n----------------------------------------\n[개강파티 안내]\n\n안녕하세요, 학생회장입니다. \n\n오늘 19시에 안암 아줌마 치킨에서 개강파티가 예정되어 있습니다! \n따로 모여서 이동하지 않으니, 개별적으로 와주시면 감사하겠습니다.\n\n*실수요조사를 신청하지 않았으나 참여를 희망하시는 분들은 학생회장에게 연락주시면 감사하겠습니다.\n\n| 문의: 학생회장 원준혁(010-****-****)\n\n장소: [네이버지도]\n안암아줌마치킨 고대점\n서울 성북구 고려대로24길 37\nhttps://naver.me/FPe59WOg\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n안암아줌마치킨(70명) - 예약금 30, 인당 2만원으로 계산, 치킨 무제한",
