                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2026.03.16 오후 3:24 쨌 학생회장 원준혁\n----------------------------------------\n[🐯합동응원전 및 연대 합동 뒤풀이 실수요조사🐯]\n\n안녕하세요 D반 학생회장입니다. 합동응원전 좌석 및 일정이 확정되어 실수요조사를 진행하려고 합니다. 이번 합동응원전은 3/20(금) 고려대 녹지운동장에서 진행됩니다. 합동응원전은 신입생 재학생 상관없이 인원이 많을 경우 엑셀 난수추첨을 통해서 결정합니다.\n\n📍자전 D반 배당 좌석: 39석\n📍뒤풀이 1차: 안암 고품콩 (22:00- 오전 1:00)\n📍뒤풀이 2차: 안암 유자유김치떡볶이 (1:30-4:30)\n\n📎계좌: 토스뱅크 [계좌번호 마스킹] 우상준\n📎예약금: 1차/2차 참석시 11,000원, 1차+2차 참석시 22,000원\n\n구글폼 : https://forms.gle/oqxQBRjyWGz2aodx5\n기한 : ~3/18(수) 23:59\n\n이번 실수요조사에서는 예약금을 부과하고 있습니다. 예약금을 입금해야 참석으로 간주되오니 잊지말고 입금 부탁드리겠습니다. 행사 전날 혹은 당일 취소 시, 예약금은 환불이 불가능하다는 점 양해바랍니다.\n\n*반드시 참여자 본인의 이름으로 송금 부탁드립니다.\n\n| 문의: 학생회장 원준혁, 부학생회장 우상준\n\n??[공지 2] 2026.03.16 오후 8:56 쨌 학생회장 원준혁\n----------------------------------------\n[응원OT 전날 최종 공지]\n\n안녕하세요, 학생회장입니다.\n\n드디어 익일 응원OT가 예정되어 있습니다. 즐겁고 신나게 응원OT 행사를 즐기기 전, 몇 가지 안내사항 전달드립니다.\n\n📍 D반 배정 좌석 수와 응원OT 신청 인원이 동일하여 실수요조사에 응답하신 분들 전원이 응원OT에 참여 가능합니다.\n\n📍 익일 동원글로벌리더쉽홀 앞 공터에서 16:30까지 집결하여 이동할 예정입니다. 자유전공학부 입장 시간에 맞춰 이동하므로, 시간 엄수 부탁드립니다.\n\n📍 자유전공학부 좌석은 첨부드린 사진의 \"N구역\"입니다. 단체입장 시 ADCB 순으로 앞에서부터 착석 예정입니다.\n\n📍 단체 입장이 불가능하여 늦게 참여 또는 실수요조사에 응답하지 않았으나 참여를 원하시는 분들께서는 학생회장에게 \"개인톡\"으로 연락 부탁드립니다. 이 경우, 화정체육관에서 \"18:30부터 개인 입장\" 가능합니다.\n\n??[공지 3] 2026.03.16 오후 11:21 쨌 학생회장 원준혁\n----------------------------------------\n사진 첨부를 빠트려서 올립니다.\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 예결특위 3차 회의\n• 일시: 2026.03.16\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
