                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 6건)]\n\n??[공지 1] 2026.03.19 오전 1:29 쨌 학생회장 원준혁\n----------------------------------------\n[합응 뒤풀이 추첨 명단 공지]\n\n안녕하세요, D반 학생회장단입니다. 합동응원전과 뒤풀이 1차, 2차 모두 신청인원이 예약인원을 초과한 관계로 부득이하게 추첨을 진행하게 되었습니다.\n합동응원전 행사는 사전에 구글폼에 공지한 바와 같이, 가수요 참여자 우선 배정이 이루어져 총 39자리 중 가수요 참여자 25명을 제외한 14인을 뽑았습니다. \n뒤풀이 1차와 2차는 각각 38인, 23인 추첨 진행하였습니다.\n\n- 추첨으로 진행된 만큼 참여할 수 없는 인원들을 고려해 당일 취소 및 환불은 불가능하다는 점 다시 한번 말씀드립니다. \n만약 참여가 불가해진다면 꼭!!! 행사 전날까지 학생회장단에 말씀해 주시길 바랍니다.\n\n- 당첨되셨지만 행사 및 뒤풀이 참여를 포기를 하신다면 다음 순서 학우분께 참여권이 전달됩니다.\n\n- 이례적으로 추첨을 진행하는 만큼 참여하지 못하시는 분들께는 행사 전후 차례대로 환불이 이루어질 예정입니다.\n\n감사합니다. \n\n| 문의: 학생회장 원준혁, 부학생회장 우상준\n\n??[공지 2] 2026.03.19 오후 2:54 쨌 학생회장 원준혁\n----------------------------------------\n[교류반 일일호프 스태프 모집 공고]\n\n안녕하세요, 자유전공학부 D반 제18대 학생회 Duet 학생회장단입니다.\n\nD반의 교류반 🦅연세대학교 에버나인🦅 과 함께 진행하는 🍻일일호프에 함께할 스태프를 모집합니다!\n\n일일호프에서 교류반과 함께하며 친분을 쌓는 동시에, 다양한 경험을 통해 색다르고 즐거운 추억을 만들 특별한 기회입니다.\n\n✨막강 D반과 에버나인✨이 합심하여 함께 운영하는 일일호프에서, 다시 없을 대학생활의 낭만을 즐겨보시길 바랍니다!\n\n많은 관심 부탁드립니다.\n\n 📎 일자: 4/4 (토)\n 📎 시간: 16:00 ~ 익일 2:00 (이후 뒤풀이가 예정되어 있습니다.)\n 📎 인원: 8명 (선착순으로 모집)\n 📎 신청폼: https://forms.gle/FT7o6NfBEbL22xpTA\n\n 📌 가능한 한 모든 시간대에 참여 가능하신 분만 신청해주시기 바랍니다.\n 📌 선착순 8명 모집 후 마감됩니다.\n\n\n| 문의: D반 학생회장 원준혁\n\n??[공지 3] 2026.03.19 오후 8:11 쨌 학생회장 원준혁\n----------------------------------------\n뒤풀이 2차(유자유) 충원 안내\n\n연대 측 인원 미달로 아래 9분 충원 되셨습니다. 이 중 뒤풀이 2차에 참여하지 않으실 분들은 개별적으로 연락 부탁드립니다.\n\n문*림(180)\n변*민(099)\n김*은(116)\n오*희(132)\n배*준(085)\n김*영(112)\n장*진(101)\n김*현(103)\n이*서(094)\n\n??[공지 4] 2026.03.19 오후 8:14 쨌 학생회장 원준혁\n----------------------------------------\n공지글 수정했습니다! 다시 확인 부탁드립니다\n\n??[공지 5] 2026.03.19 오후 10:27 쨌 학생회장 원준혁\n----------------------------------------\n[합동응원전 단체입장 안내]\n\n- 16시 30분까지 동글리 앞으로 모여주세요.(시간엄수!!)\n- 되도록이면 단체입장 하시길 바랍니다.\n- 물 개별적으로 챙겨오시길 바랍니다! 준비된 생수가 그리 많지 않습니다.\n- 티켓은 동글리에 모이면 분배하도록 하겠습니다.\n- 22시쯤 뒤풀이를 위해 퇴장 예정입니다.\n- 좌석이 플로어여서 가방 둘 자리가 없을뿐더러 바닥에 두면 분실될 수 있으니 참고 부탁드립니다 되도록 짐을 가볍게 하고 갑시다(찾기 어렵습니다)!\n\n즐거운 추억을 쌓는 것도 좋으나 안전이 항상! 우선임을 숙지해주시길 바랍니다. 목, 허리, 전신 스트레칭 한 번씩 꼭 해주세요. 밤이 되면 날이 쌀쌀해지니 얇은 겉옷 하나쯤 챙겨오시는 것도 좋을 듯 합니다. 그럼 내일 뵙겠습니다!\n\n??[공지 6] 2026.03.19 오후 10:28 쨌 학생회장 원준혁\n----------------------------------------\n[합동응원전 개인 입장(늦참) 및 미신청자 입장 안내]\n\n( 합응 명단에 계시고 늦참인 경우 )\n- 개인 입장하시는 분들은 3/20(금) 10:00-16:00 중 학생회실에서 티켓 수령 바랍니다.\n- 18시 30분부터 개인입장(늦참) 하실 분들은 이 공지에 체크표시 부탁드립니다! 인원체크를 위함이니 꼭 해주시길 바랍니다.\n\n( 합응 명단에 없으신 경우 )\n- 티켓을 수령하지 못하신 분들 (난수 추첨 배정 X 또는 합응 신청 X) 중 합응 입장을 원하시는 분들은 20시부터 입장 가능하다고 합니다! (정확한 시간은 입장 상황에 따라 유동적 변경) 이 경우에도 학생회장에게 연락 부탁드립니다.\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 회해위 1차 회의\n• 일시: 2026.03.19\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
