                               "noticeText":  "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2026.03.24 오후 2:50)\n----------------------------------------\n일일호프 스태프 모집 마감되었습니다. 확정 인원들은 채팅방에 초대 완료했습니다!\n많은 분들이 지원해주셨으나 선착순 및 가능한 일정 기준으로 마감하여, 지원해주신 모든 분들과 일하지 못해 아쉽습니다! 다음에 좋은 기회로 또 찾아뵙길 바라겠습니다.\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[2026학년도 상반기 자유전공학부 D반 신입생 대표 · 고학번 대표 선거 결과 공고]\n• 투표 일시: 2026.03.24.(화) 00:00 ~ 03.26.(목) 18:00 (구글폼 온라인 투표, 학생증 인증)\n• 개표 결과:\n  1. 신입생 대표 단일후보 채현찬(26): 총원 30명(회칙 제86조 제6항) 중 17명 투표(투표율 56.67% ≥ 25% 성립) → 찬성 16표(94.12%), 기권 1표로 당선\n  2. 고학번 대표 단일후보 김민정(24): 총원 60명(회칙 제87조 제6항) 중 15명 투표(투표율 25.00% ≥ 25% 성립) → 찬성 15표(100%)로 당선\n• 전임 대표(민준기·김도현) 임기 만료 공고일: 당선 공고 48시간 후인 2026.03.29.(일) 00:00부",
