                               "noticeText":  "[📢 카카오톡 단체방 공식 공지]\n• 발신: 복지국장 김동운 (2026.04.03 오후 3:07)\n----------------------------------------\n[2026학년도 1학기 D반 중간고사 간식행사 간식 수요조사]\n\n안녕하세요, 제18대 D반 학생회 Duet 복지국입니다.\n\n학우 여러분의 1학기 중간고사 응원을 위한 [D반 중간고사 간식행사]의 진행에 앞서 간식에 대한 수요조사를 진행합니다!\n\n구글폼: https://forms.gle/DCucWVffMJssd6bN9\n\n✅ 참여 방식 : 구글폼 작성하여 제출\n\n✅ 수요 조사 기간 : ~4/5(일) 23:59\n\n❗수요조사 결과 수요가 높은 3가지 간식을 선택하여 간식행사가 진행될 예정입니다.\n\n❗모든 학우분들의 수요를 반영할 수 없다는 점 양해 부탁드립니다.\n\n문의: 복지국장 김동운\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[연세대학교 상경9반(경제9반 에버나인) X 고려대학교 자전D반 합동 일일호프]\n📅 일시: 2026년 4월 3일(금) 18:00~\n📍 장소: 신촌 바플라이 3호점 단밤 ([합석가능] [미팅 테이블] 운영)\n🎰 3호점만의 SPECIAL EVENT:\n1. 오늘의 내 행운은~? 테이블 로또 번호 추첨!\n2. 게임 한 판 하실래요? 테이블 간 칩을 건 게임!\n3. 요즘 즐겨듣는 노래는.. 신청곡 즉석 반영!\n\n[만우절 중짜(중앙광장 짜장면 데이) 안내]\n• 일시: 2026.04.01.(수) 12:00 타임(15명) / 13:00 타임(9명)\n• 장소: 고려대학교 중앙광장 잔디밭 (신입생 공지용 약도와 재학생 공지용 약도 구역을 다르게 표시한 만우절 깜짝 이벤트!)",
