                               "noticeText":  "[📢 카카오톡 단체방 공식 공지]\n• 발신: 복지국장 김동운 (2026.04.10 오후 5:55)\n----------------------------------------\n[2026학년도 1학기 D반 중간고사 간식행사]\n\n안녕하세요, 제18대 D반 학생회 Duet 복지국입니다.\n\n학우 여러분의 1학기 중간고사 응원을 위해 [D반 중간고사 간식행사]를 진행합니다! 많은 참여 부탁드립니다.\n\n학우분들을 대상으로 한 간식 수요조사 결과 육회비빔밥, 닭강정, 포케가 간식으로 선정되었습니다. 수요조사에 대한 많은 관심 감사드립니다.\n\n간식행사 신청 구글폼: https://forms.gle/hBhgMrjpT3cN4ysA9\n\n🎁참여 방식 : 사전 신청 기간에 구글폼 선착순 신청 후, 반실에서 대면 수령\n🎁사전 신청 시간 : 26. 04. 13.(월) 17시~ (선착순 25명 마감)\n*17시 이전에 구글폼 제출 시 무효 처리되니, 꼭 17시 이후에 제출하시기 바랍니다.\n🎁실제 수령 시간 : 26. 04. 16.(목) 18시 ~ 19시\n🎁실제 수령 장소 : 구법학관 D반 반실\n🎁메뉴 :  육바연 육회덮밥+피크닉 (10개) // 레드컵스 1인세트C(닭강정, 떡볶이)+콜라 (10개) // 포케올데이 연어회 곡물밥 포케+제로사이다 (5개)\n\n❗학생회비 납부자만 신청 가능합니다.\n❗대면으로 본인이 수령함이 원칙입니다.\n❗명단 확정자(사전 신청자 가운데 선착순 25명)에 한하여 나눔합니다.\n❗메뉴 선택은 행사 당일 선착순으로  진행합니다.\n\n문의: 복지국장 김동운\n제작: 홍보국원 박준원\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 4월 1차 반실 정기 청소\n• 일시: 2026.04.10\n• 담당 국서: 복지국\n• 진행 상태: 완료",
