                               "noticeText":  "[📢 카카오톡 단체방 공식 공지]\n• 발신: 기획국장 김채은 (2026.04.12 오후 7:29)\n----------------------------------------\n[2026-1학기 중간고사 스터디윗D]\n\n안녕하세요, Duet 기획국입니다! 따뜻한 봄바람과 함께 2026 스터디윗D가 시작되었습니다🌸 학우들과 함께 공부하며 좋은 학점도 챙겨가고 푸짐한 경품도 받을 수 있는 기회 되시길 바랍니다! 이번 스터디윗D는 참여한 모든 학우분들께 소정의 상품을 드리고 있으니 많은 관심과 참여 부탁드립니다~~\n\n[ 열품타 초대링크 ]  https://link.yeolpumta.com/P3R5cGU9Z3JvdXBJbnZpdGUmaWQ9NTgzNTE0OA==\n(비밀번호 : 2009)\n\n[ 참여 방식 ]\n1. 공유된 링크를 통해 \u0027열품타\u0027 앱 접속 후 닉네임을 이름+학번 뒤 3자리로 설정해주세요 (ex. 원준혁 088).\n2. 매일 공부를 시작할 때 타이머를 재생해주시고, 끝낼 때 타이머를 멈춰주세요.\n3. 🚨중요🚨잊지 말고 매일 \u0027하루 한 번 공부 인증\u0027 미션을 수행해주세요! 미수행 시 경품 지급 대상에서 제외될 수 있습니다.\n** 타이머를 실수로 끄지 않은 경우를 배제하기 위해 최대 집중 시간이 5시간을 초과한 날은 집계에서 제외합니다 **\n\n🔥경품 추첨\n경품 추첨은 10일의 기간 동안 \u00276일 이상 출석\u0027하고 \u0027총 공부시간 25시간 이상\u0027인 학우분들에 한하여 진행합니다.\n*** 이번 스터디윗D부터 경품 추첨 기준을 달성한 학우 전원에게 소정의 상품을 증정합니다.\n\n✅경품 목록\n-cgv 영화 티켓 1매 (1명)\n-배달의민족 1만원권 (2명) \n-투썸플레이스 떠먹는 아이스박스 (3명)\n\n| 제작 : 홍보국장 이윤주\n| 문의 : 기획국장 김채은, 학생회장 원준혁\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[2026-1학기 중간고사 간식행사 \u0026 스터디윗D 진행 내역]\n• 중간고사 간식행사 (복지국):\n  - 4/3(금)~4/5(일): 학우 대상 사전 간식 메뉴 수요조사 실시 (제18대 공약 이행)\n  - 4/10(금): 간식행사 공지 카드뉴스 업로드\n  - 4/16(목): 중간고사 간식 배부 완료\n• 중간고사 스터디윗D (기획국):\n  - 4/12(일): 카드뉴스 업로드 / 4/13(월)~4/22(수) 10일간 진행\n  - 개편 사항: ① 기준 달성자 전원 소정의 상품 지급(달성제) + 소수 인원 고액 Best 경품 추첨 혼합 방식 도입, ② 시험 과목 외 자격증·어학 등 자율 공부 시간도 모두 인정!",
