                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 4건)]\n\n??[공지 1] 2026.04.16 오후 12:57 쨌 복지국장 김동운\n----------------------------------------\n[D-Day 간식행사 배부 리마인드]\n\n안녕하세요, Duet 입니다.\n\n금일 17시 50분에 반실에서 간식 배부가 예정되어 있습니다. 사전에 공지한 명단 인원에 한하여 배부하며, 배부 시간 이후 남은 간식은 명단 관계 없이 선착순 배부 예정입니다.\n\n배부 시간: 17시 50분 ~ 19시 00분\n\n일정 참고하시어 꼭 받아가시길 바랍니다! 감사합니다.\n박성산님이 나갔습니다.\n\n??[공지 2] 2026.04.16 오후 3:01 쨌 학생회장 원준혁\n----------------------------------------\n📢 [자전 D반] 4월 주요 추천 채용 공고 안내\n\n자전 D반 학생들의 다양한 진로 선택의 길을 열기 위해 인캐쳐가 엄선한 4월의 핫한 채용 소식을 전해드립니다. 단순한 공고를 넘어 대학생 맞춤형 직무들로 준비했습니다.\n\n🚀 이번 주 주목해야 할 채용 TOP 2\n\n1️⃣ [Dr.Different] Marketing Operator (경력 무관)\n특징: 재택근무 가능, 경력 상관없이 지원 가능!\n주요업무: 인플루언서 시딩 및 SNS 콘텐츠 운영 관리\n우대사항: 뷰티/화장품 관심자, 틱톡/인스타그램 헤비 유저\n\n2️⃣ [오늘의집] 오프라인 전략 매니저 (신입 계약직)\n특징: 자율 출근제 시행, 서울 오피스 근무\n주요업무: 물류 최적화 전략 수립, AI 기반 워크플로우 전환, P\u0026L 리포팅\n우대사항: 상경/회계/세무 관련 전공자 또는 리테일 물류 경험자\n\n🔒 이용 안내 (필독)\n인캐쳐는 대학생 인증을 거친 회원만 이용 가능한 전용 플랫폼입니다. 일반 구직 사이트보다 경쟁력 있는 직무와 혜택을 지금 바로 확인해 보세요!\n\n✅ 상세 공고 확인 및 지원하기\n👉 https://www.incatcher.com/\n\n??[공지 3] 2026.04.16 오후 6:22 쨌 복지국장 김동운\n----------------------------------------\n[26-1 중간고사 간식행사 잔여 간식 배부 안내]\n\n안녕하세요, Duet 복지국입니다.\n\n잔여 간식 배부  시간을 앞당겨 18시 30분부터 배부 예정입니다!\n\n현재 레드컵스 1인세트C+콜라 3개 남아있습니다.\n\n??[공지 4] 2026.04.16 오후 6:31 쨌 복지국장 김동운\n----------------------------------------\n간식행사 배부 마감입니다!\n\n많은 관심 감사합니다:)\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[2026-1학기 중간고사 간식행사 \u0026 스터디윗D 진행 내역]\n• 중간고사 간식행사 (복지국):\n  - 4/3(금)~4/5(일): 학우 대상 사전 간식 메뉴 수요조사 실시 (제18대 공약 이행)\n  - 4/10(금): 간식행사 공지 카드뉴스 업로드\n  - 4/16(목): 중간고사 간식 배부 완료\n• 중간고사 스터디윗D (기획국):\n  - 4/12(일): 카드뉴스 업로드 / 4/13(월)~4/22(수) 10일간 진행\n  - 개편 사항: ① 기준 달성자 전원 소정의 상품 지급(달성제) + 소수 인원 고액 Best 경품 추첨 혼합 방식 도입, ② 시험 과목 외 자격증·어학 등 자율 공부 시간도 모두 인정!",
                               "thought":  "• 원래 공약은 스터디윗D를 100% 전원 달성제로 바꾸는 것이었으나, 시뮬레이션을 해보니 참여자가 늘어날수록 1인당 상품 금액이 2,500원 수준으로 급락해 오히려 기존 참여 학우들이 아쉬워하는 문제가 있었습니다.\n• 4/1 제4차 국장단회의에서 고학번 대표(김민정)가 \u0027기준 달성자 전원에게 소정의 상품을 주면서, 동시에 1~2명에게 높은 금액의 Best 경품을 추첨 지급하자\u0027는 혼합제 아이디어를 내주어 완벽한 절충안을 찾았습니다!"
