                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 4건)]\n\n??[공지 1] 2026.05.23 오후 1:39 쨌 학생회장 원준혁\n----------------------------------------\n파일: 2026 상반기 D반 확대운영위원회 회의 안건지.pdf\n\n??[공지 2] 2026.05.23 오후 5:57 쨌 학생회장 원준혁\n----------------------------------------\nhttps://meet.google.com/tfx-yptm-rwj\n\n??[공지 3] 2026.05.23 오후 5:58 쨌 학생회장 원준혁\n----------------------------------------\n2026 상반기 확대운영위원회 온라인 회의실 링크입니다!\n\n??[공지 4] 2026.05.23 오후 6:19 쨌 학생회장 원준혁\n----------------------------------------\n파일: 2026 상반기 D반 확대운영위원회 회의 안건지-1.pdf\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[2026 D반 총MT 안내]\n• 일시: 2026.05.08.(금) ~ 05.09.(토) (1박 2일)\n• 장소: 대성리 뜨락펜션 (경기도 남양주시 화도읍 모꼬지로17번길 37-34, 60명 규모)\n• 참가비: 40,000원 (홍보국 커스텀 주루마블 및 기획국 레크리에이션 진행)\n\n[26-1 중간고사 간식행사 \u0026 스터디윗D 만족도 조사]\n• 기간: 2026.05.07.(목) ~ 05.20.(수)\n• 참여 방법: 반실 부착 및 카드뉴스 내 QR코드 스캔 (객관식 위주, 소요 시간 1~2분)",
