                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 2건)]\n\n??[공지 1] 2026.05.31 오후 4:58 쨌 학생회장 원준혁\n----------------------------------------\n[2026년 상반기 확대운영위원회 회의 결과 공고]\n\n회의록 및 세부사항은 자유전공학부 학생회 네이버 카페에서 열람하실 수 있습니다.\n\n| 문의: D반 학생회장 원준혁\n| 제작: 홍보국원 박준원\n\n??[공지 2] 2026.05.31 오후 5:02 쨌 학생회장 원준혁\n----------------------------------------\n[5월 집행위원회 월간보고]\n\n안녕하세요, 자유전공학부 D반 제18대 학생회 Duet입니다.\n\n다음과 같이 5월 집행위원회 업무 보고를 안내드립니다. 자세한 사항은 카드뉴스를 참고하시길 바랍니다.\n\n감사합니다.\n\n| 문의: 학생회장 원준혁\n| 제작: 홍보국장 이윤주\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[5월 월간보고 (2026.05.31)]\n• 담당 국서: 홍보국\n• 진행 상태: 완료\n• 해당 월의 집행위원회 국서별(학생회장단·기획국·복지국·홍보국) 활동 내역 카드뉴스 슬라이드(5장)를 상단 이미지 뷰어 및 하단 월간보고 표에서 확인하실 수 있습니다.",
