                               "noticeText":  "[📢 카카오톡 단체방 공식 공지]\n• 발신: 복지국장 김동운 (2026.06.04 오후 3:54)\n----------------------------------------\n[2026학년도 1학기 D반 기말고사 간식행사]\n\n안녕하세요, 제18대 D반 학생회 Duet 복지국입니다.\n\n학우 여러분의 1학기 기말고사 응원을 위해 [D반 기말고사 간식행사]를 진행합니다! 많은 참여 부탁드립니다.\n\n학우분들을 대상으로 한 간식 수요조사 결과 육회비빔밥, 이삭토스트, 밥버거+컵라면이 간식으로 선정되었습니다. 수요조사에 대한 많은 관심 감사드립니다.\n\n간식행사 신청 구글폼: https://forms.gle/RzRqphmxbZXHSbvX6\n\n🎁참여 방식 : 사전 신청 기간에 구글폼 선착순 신청 후, 반실에서 대면 수령\n🎁사전 신청 시간 : 26. 06. 08. (월) 17시~ (선착순 32명 마감)\n*17시 이전에 구글폼 제출 시 무효 처리되니, 꼭 17시 이후에 제출하시기 바랍니다.\n🎁실제 수령 시간 : 26. 06. 11. (목) 18시 ~ 18시 40분\n🎁실제 수령 장소 : 구법학관 D반 반실\n🎁메뉴 :  육바연 육연덮밥+제로콜라 (10개) // 이삭토스트 햄치즈 토스트, 포테이토팝+애사비소다 (10개) // 봉구스밥버거 김치제육밥버거+진짬뽕 컵라면+제로사이다 (12개)\n\n❗학생회비 납부자만 신청 가능합니다.\n❗대면으로 본인이 수령함이 원칙입니다.\n❗명단 확정자(사전 신청자 가운데 선착순 32명)에 한하여 나눔합니다.\n❗메뉴 선택은 행사 당일 선착순으로  진행합니다.\n\n문의: 복지국장 김동운\n제작: 홍보국장 이윤주\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[2026-1학기 D반 기말고사 간식행사 안내]\n• 사전 수요조사: 5/27(수) ~ 5/29(금)\n• 신청 일시: 6월 8일(월) 17:00~ (공지방 구글폼 링크, 학생회비 납부자 한정)\n• 배부 일시: 6월 11일(목) 18:00 ~ 18:40 (D반 반실)\n• 간식 메뉴 (3종):\n  1. 육회바른연어 — 육연덮밥 + 제로콜라\n  2. 이삭토스트 — 햄치즈 토스트, 포테이토팝 + 애사비소다\n  3. 봉구스밥버거 — 김치제육밥버거 + 진짬뽕(컵라면) + 제로사이다\n\n[기말고사 스터디윗D : Summer 안내]\n• 일시: 6/8(월) ~ 6/17(수) (10일간)\n• 방법: 열품타 D반 그룹 가입 (닉네임: 이름+학번 뒤 세 자리, 예: 김채은116), 10일 중 6일 이상 출석 \u0026 총 25시간 이상 공부 (일 최대 집중시간 5시간 초과 제외)\n• 혜택: 기준 달성 시 전원 소정의 상품 증정 + Best 경품 추첨 (CGV 영화 티켓 1명, 배민 1만원권 2명, 투썸 아이스박스 3명)",
                               "thought":  "• 1학기 중간고사에 이어 기말고사에서도 \u0027사전 메뉴 수요조사(5/27~29)\u0027를 거쳐 학우들이 가장 원했던 메뉴(육연덮밥, 이삭토스트, 봉구스밥버거+컵라면)로 구성해 호응이 매우 좋았습니다.\n• \u00272026 친해져도 Dㅐ?\u0027 역시 3월 10일부터 6월 7일까지 약 3개월간의 장기 레이스를 마치고 6월 11일에 최종 채점 결과 발표와 우수조 상품 지급(예산 158,000원)까지 깔끔하게 마무리했습니다."
