                               "title":  "26-1 중간고사 스윗디 공지",
                               "summary":  "사전 수요조사 기반 기말 간식행사(육회바른연어·이삭토스트·봉구스밥버거) / Summer 스터디윗D(CGV·배민·투썸 + 달성자 전원 증정) / 친해져도Dㅐ? 종결",
