                               "noticeText":  "[7~8월 하계방학 주요 업무 요약]\n• 7/1(수): 기말고사 스터디윗D 경품 추첨 및 6월 월간보고 업로드\n• 7/8(수) 제6차 국장단회의 \u0026 8/7(금) 제7차 국장단회의:\n  - 방학 중 사업량을 고려해 7월·8월 월간보고를 \u00277~8월 통합호\u0027로 발행 결정\n  - 자유전공학부 행정실 지원 반실 가구(소파 등) 구매 품목 및 가격대 최종 조율\n  - 전 국서 구글 드라이브 사업 아카이빙 착수\n• 8/26(수): 여름방학 맞이 반실 대청소 진행\n• 9/1(화): 반실 내 고장 난 사무용 바퀴 의자(60×50×93cm) 행정실 \u0027미등록 불용품 신고서\u0027 제출 및 폐기 배출",
