                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2026.09.01 오후 12:08 쨌 학생회장 원준혁\n----------------------------------------\n[2학기 응원OT 및 뒤풀이 실수요조사]\n\n안녕하세요! D반 제18대 학생회 Duet입니다. 2학기 응원OT 및 뒤풀이 실수요조사를 진행하고자 합니다. 참여를 원하는 학우분들께서는 신청 기간 내에 구글폼 제출과 함께 예약금 입금을 완료해주시길 바랍니다. 많은 관심 부탁드립니다! \n\n📍일시: 9/9(수)\n📍신청 기간: ~ 9월 6일(일) 23:59\n📍뒤풀이 장소 및 일시: 막걸리찬가 22:00\n📎 뒤풀이 예약금: 10,000원\n📎 입금계좌: 토스뱅크 [계좌번호 마스킹] 우상준\n📎 입금명: 학번+성명 (ex. 25우상준)\n📎 신청 링크: https://forms.gle/csBQzQN6mGYLPiLX9\n\n❗️D반에 배정된 응원OT 좌석은 26석, 뒤풀이 좌석은 28석입니다. 신청자가 많을 경우, 난수 추첨을 통해 배정이 이루어질 예정입니다.  \n❗️폼 작성과 더불어 예약금 입금이 완료되어야 참석으로 간주되오니 잊지 말고 입금하시길 바랍니다. 행사 전날 혹은 당일 취소 시 예약금은 환불이 어려운 점 양해 부탁드립니다.\n❗️구체적인 집결 시간, 장소 등의 응원OT 관련 사항들은 추후 상세히 공지될 예정입니다. \n\n문의: D반 학생회장 원준혁 010-****-****\n\n??[공지 2] 2026.09.01 오후 4:57 쨌 학생회장 원준혁\n----------------------------------------\n[마감 D-1 리마인드]\n2학기 개강파티 신청 내일 23:59까지입니다. 많은 관심과 신청 부탁드립니다!\n\n??[공지 3] 2026.09.01 오후 9:04 쨌 학생회장 원준혁\n----------------------------------------\n🚨 [자전 D반 X 인캐쳐] 이 혜택, 남들 다 챙기고 나만 놓치면 너무 아깝잖아…👀\n이번 달 최대 60% OFF🔥9월 개강 준비, 정가 주고 사면 손해예요!\n\n🎁 인캐쳐 9월 개강 특가 OPEN!\n새 학기 시작하면서 필요한 거 하나씩 사다 보면\n생각보다 지출이 커지죠? 🥲\n\n1️⃣ EXTREME | 9월 14일까지\n💪 운동하는 사람이라면 놓치면 아쉬운 혜택!\n최대 44% OFF 특가로 EAA부터 다양한 인기 제품까지!\n\n2️⃣ Dewixir Formula | 최저가 보장 \n🫧 간결하게, 그러나 확실한 효과! 스킨케어 브랜드!\n여드름성 피부 완화 클렌징 바부터 미스트와 앰플을 합친 미스트까지\n\n3️⃣ Heroes of Korea | 9월 한정 개강 특가\n🌿 가을에 어울리는 향을 찾고 있다면?\n\n4️⃣ NICK\u0026NICOLE | 최대 60% OFF\n🖤 학교에 뭐 입고 갈지 고민이라면?\n개강룩 고민 끝~!\n\n5️⃣ BoilTale X Incatcher | BAG SPECIAL\n👜 매일 들어도 질리지 않는 감성적인 가방들,\n최대 30% OFF 특별 할인 진행!\n(인캐쳐 사이트 배너를 클릭하면 더많은 패밀리세밀을 확인하실 수 있어요!)\n\n6⃣ 파나소닉 | 최대 31% 할인\n해외여행 때, 변압기 없이 챙겨갈 수 있는 프리볼트 고데기까지!\n\n이번 개강 준비는 인캐쳐에서 똑똑하게 챙겨보세요! 🔥\n\n👉 지금 9월 혜택 확인하기\n인캐쳐 바로가기 www.incatcher.com\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 응원OT 및 뒤풀이 실수요조사\n• 일시: 2026.09.01 ~ 09.06\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
