                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 2건)]\n\n??[공지 1] 2026.09.04 오전 11:19 쨌 학생회장 원준혁\n----------------------------------------\n[흑잠 배부 안내]\n금일 10시부터 흑잠 배부를 진행합니다. \n\n○공식 배부 일정○\n9월 4일(금), 7일(월), 8일(화)(총 3일) 10시-18시\n(불가피하게 주말만 수령 가능하신 분들께서는 D반 신입생 대표에게 개인톡을 남겨주시면 감사드리겠습니다)\n\n○준비물○\n학생증(모바일 가능) 등 본인 확인이 가능한 서류\n\n○배부방식○\n-재실 인원이 있는 경우, 재실 인원에게 학번 말씀해주시면 재실 인원이 도와드리겠습니다.\n-재실 인원이 없는 경우, 반실에 적혀있는 전화번호 or D신 채현찬에게 개인톡(학번과 사이즈 및 이니셜 여부 보내기) 후 가져가시면 됩니다.\n\n임의로 가져가시지 않도록 주의부탁드립니다.\n\n문의:D반 신입생대표 채현찬(010-****-****)\n\n??[공지 2] 2026.09.04 오후 6:37 쨌 학생회장 원준혁\n----------------------------------------\n금일 개강파티 오시는 분들 19시에 박군포차로 오시면 됩니다!\nhttps://maps.app.goo.gl/aAdbCUNqaqpg5WRB8\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 26-2학기 개강파티\n• 일시: 2026.09.04\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
                               "thought":  "• 노션(Notion) 캘린더 데이터베이스에서 동기화된 제18대 학생회 Duet 공식 일정입니다. 관리자 모드에서 [✏️ 코멘트/공지 편집]을 켜면 이 일정에 대한 세부 코멘트를 자유롭게 추가하실 수 있습니다."
