                               "noticeText":  "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2026.09.18 오전 9:28)\n----------------------------------------\n[🐯2026-2학기 합동응원전 및 뒤풀이 실수요조사🐯]\n\n안녕하세요 D반 학생회장입니다. 합동응원전 좌석 및 일정이 확정되어 실수요조사를 진행하고자 합니다. \n\n이번 합동응원전은 9/22(화) 연세대(신촌) 노천극장에서 진행됩니다. 합동응원전과 뒤풀이는 정원 초과시, 엑셀 난수 추첨을 통해 명단을 확정하는 점 양해 부탁드립니다.\n\n📍자전 D반 좌석: 30석\n📍뒤풀이 1차(23석): 빠빠빠치킨 연대본점(22:00-24:00)\n📍뒤풀이 2차(13석): 설맥 신촌점(오전 00:00-2:00)\n\n📎계좌: 토스뱅크 [계좌번호 마스킹] 우상준\n📎예약금: 1차/2차 참석시 1만원, 1차+2차 참석시 2만원\n📎신청 기간: ~9/20(일) 23:59\n📎구글폼: https://forms.gle/9xbFDG29Fdc7qNkk7\n\n❗️폼 작성과 더불어 예약금 입금이 완료되어야 참석으로 간주되오니 잊지 말고 입금하시길 바랍니다. 행사 전날 혹은 당일 취소 시 예약금은 환불이 어려운 점 양해 부탁드립니다.\n❗️집결 시간 및 장소는 추후 공지드리겠습니다.\n\n| 문의: 학생회장 원준혁\n김동림님이 25 D 김윤정님을 초대했습니다.\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 2학기 합동응원OT 및 뒤풀이 실수요조사\n• 일시: 2026.09.18 ~ 09.20\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
