                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 2건)]\n\n??[공지 1] 2026.09.27 오전 11:39 쨌 학생회장 원준혁\n----------------------------------------\n[2026 정기 고연전 야구 경기 단체석 신청]\n\n안녕하세요. D반 제18대 학생회 Duet입니다. \n티켓 없이 단체 입장하는 정기 고연전 야구 종목에 대해 D반 단체석 신청을 받고자 합니다. 아래 구글폼을 통해 신청해주시면 감사하겠습니다.\n\n📍자전 D반 좌석: 야구 43명 \n📍고연전 야구 경기 일시: 10/2(금) 11:00 (개막식 10:00) \n📍고연전 야구 경기 장소: 잠실 종합운동장 야구장\n📍신청 기한: 9/30(수) 23:59까지\n📍신청 구글폼: https://forms.gle/pc1Z7AwEXTVxs5669 \n\n❗️신청 인원이 좌석 수를 초과한다면 엑셀 난수 추첨을 통해 명단을 확정하도록 하겠습니다. 이 경우, 추후 공지 드리겠습니다.\n❗️단체 입장 집결 시간 및 장소 등은 추후 자세히 공지하도록 하겠습니다. 감사합니다. \n\n| 문의: 학생회장 원준혁\n\n??[공지 2] 2026.09.27 오전 11:40 쨌 학생회장 원준혁\n----------------------------------------\n정기 고연전 뒤풀이 및 기차놀이도 9/30(수)까지 실수요조사 진행 중에 있습니다!\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 고연전 야구 단체석 신청\n• 일시: 2026.09.27 ~ 09.30\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
