                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 7건)]\n\n??[공지 1] 2026.10.01 오전 12:16 쨌 부학생회장 우상준\n----------------------------------------\n[정기 고연전 야구 단체 관람 좌석 추첨 안내]\n\n안녕하세요. D반 부학생회장입니다. \n2026 정기 고연전 야구 종목 단체 실수요조사가 마감되었습니다.\n추첨은 잠시 후인 12:30에 진행될 예정입니다. D반은 난수 내림차순으로 총 45석 가능합니다! \n이전 공지의 스프레드시트에 이상이 있는지 확인 부탁드리며, 발견하면 학생회장단에게 개인 연락 남겨주시면 감사하겠습니다. \n스프레드시트 확인 링크: https://docs.google.com/spreadsheets/d/1QE0UpRHavjCRlyHIHEHfchBLBnSmbns5oYIM_6GiAIQ/edit?usp=sharing\n\n감사합니다. \n\n| 문의: 학생회장 원준혁\n\n??[공지 2] 2026.10.01 오전 12:38 쨌 학생회장 원준혁\n----------------------------------------\n[정기고연전 야구 단체 관람석 명단 확정 안내]\n\n안녕하세요, D반 학생회장입니다.\n엑셀 난수 추첨이 완료되어 다음과 같이 야구 단체 관람석 명단을 공지드립니다. 감사합니다.\n\n* 정기고연전 야구 단체 관람석 입장 및 안내 사항은 추후 공지 드리겠습니다. \n\n| 문의: D반 학생회장 원준혁\n\n??[공지 3] 2026.10.01 오후 4:52 쨌 학생회장 원준혁\n----------------------------------------\n[10/2(금) 2026 정기 고연전 야구 경기 입장 안내]\n\n안녕하세요, D반 학생회장입니다. \n고연전 야구 경기 단체 입장 안내드립니다!\n\n고연전 야구 경기의 경우 공지된 명단 내 인원에 한하여 입장 가능하며 집결 후 단체 입장 예정입니다.\n\n📍집결 일시: 10/2(금) 오전 9시 30분\n📍집결 장소: 잠실야구장 게이트 1-2 앞\n\n❗️추첨된 인원 중 단체 입장이 불가능하여 개인 입장 하실 분들께서는 학생회장에게 개인톡 부탁드립니다. \n\n❗️추첨되었으나 고연전 야구 관람에 불참 예정인 분들께서도 다른 학우들의 입장을 위해 개인톡 주시면 감사드리겠습니다.\n\n❗️행정실에서 경기 관람하며 먹을 수 있도록 한솥도시락 및 닭강정을 지원을 받아 단체입장 인원 배부 이후, 개인 입장 인원에게 선착순 배부될 예정입니다.\n\n| 문의: D반 학생회장 원준혁\n\n??[공지 4] 2026.10.01 오후 4:54 쨌 학생회장 원준혁\n----------------------------------------\n🔗 https://bit.ly/고연전야구장\n\n??[공지 5] 2026.10.01 오후 4:56 쨌 학생회장 원준혁\n----------------------------------------\n학부 공지방에서 공지된 잠실야구장 좌석표 공유드립니다!\n\n??[공지 6] 2026.10.01 오후 5:55 쨌 학생회장 원준혁\n----------------------------------------\n🚨 [인캐쳐 10월 특가] 시험기간에 살찌지 말자… 간식도 단백질로! 💪🍫 프로틴 간식 9,900원부터🔥 앰플 11,500원에 시나모롤 파자마 1+1까지?!\n\n🎁 인캐쳐 10월 특별 할인 OPEN!\n\n1️⃣ 프롬잇 | 단백질 간식 9,900원부터\n🍫 아몬드 초코볼 10,900원 / 프로틴칩 12,900원 / 단백질 쉐이크도 최대 66% OFF!\n📅 10/14까지 한정\n\n2️⃣ 나인위시스 | 앰플이 12,500원?!\n💧아이돌 톤업 바디세럼 11,500원\n\n3️⃣ 오기뜨 | 시나모롤 파자마 1+1\n💤커플파자마? 지금이 기회다!\n\n시험기간 간식부터 피부, 잠옷까지\n10월도 정가 주고 사지 말고 인캐쳐에서 챙겨가세요🔥\n\n👉 지금 10월 혜택 확인하기\n인캐쳐 바로가기 www.incatcher.com\n\n??[공지 7] 2026.10.01 오후 8:00 쨌 기획/홍보국장 장여백\n----------------------------------------\n[릴스 고연전 개최 안내]\n\n안녕하세요, Duet 기획국입니다.\n드디어 필승!전승!압승!의 고연전이 내일로 다가왔습니다! 올해는 특별히 고연전을 맞아 교류반인 에버나인과 함께하는 릴스 고연전을 개최하고자 합니다. 특히, 이번 행사는 고연전이라는 특별한 계기를 통해 에버나인과의 교류를 더욱 활성화하고, 기존의 대면 행사에서 나아가 일상 속에서도 자유롭게 소통할 수 있는 기회를 마련하고자 기획되었습니다.\n고연전의 열기를 온라인에서도 이어가며, 에버나인과 함께 색다른 추억을 만들어 갈 수 있도록 많은 관심과 참여 부탁드립니다:)\n\n✅ 행사 일정\n해당 공지가 올라간 10/1(목) 20:00부터 10/16(금) 23:59까지 \n* 행사 진행 기간 안엔 언제든지 자유롭게 신청 구글폼 제출이 가능합니다.\n\n✅ 참여 자격\n1인 이상 4인 이하 팀\n** 동일 팀원 구성으로 복수 지원(릴스 여러개 제출)은 가능하나 수상에는 최고 조회수 1건만 반영됩니다.\n\n✅ 참여 방식\n1. 개인 인스타 계정에 \u0027교류반 간 상호 교류 증진\u0027을 주제로 한 릴스를 업로드 해주세요. 🚨이때 에버나인(상경9반)과 자전D반 태그를 필수적으로 해주셔야 합니다.🚨\n2. 개인 참가가 아닌 팀 단위로 참가하는 경우, 릴스 업로드 시 팀원 전원을 공동작업자에 추가해주세요.\n3. 릴스 업로드 및 태그만으로는 릴스 고연전 참여가 불가합니다. 🚨반드시 아래 첨부되어 있는 참여 구글폼을 제출해주세요!🚨\n4. 릴스 내에서 \u0027에버나인(상경9반)\u0027 또는 \u0027연세대\u0027를 언급할 경우, 최종 점수 집계 시 해당 릴스 조회수의 5%를 가산해 드립니다!\n5. 릴스의 형식과 내용은 자유롭게 구성해 주시면 됩니다.\n🚨*** 단, 양교 교류 증진과 무관한 화제몰이 목적의 콘텐츠나 양교 및 구성원의 명예를 실추시킬 수 있는 극단적 콘텐츠는 수상에서 제외될 수 있습니다.🚨\n\n✅ 수상 릴스 선정 방식\n행사 종료 시점인 10/16(금) 23:59의 릴스 조회수를 기준으로, 조회수가 높은 순서대로 순위 결정\n\n✅경품 목록\n- 고려대 1등(1팀): 명랑핫도그 2만원권 + 삼첩분식 로제 떡볶이\n- 고려대 2등(2팀): 인절미 설빙\n- 종합 1위: 회장단 명의의 상장 + α(?)\n**** 엡나 vs 자전D반 부문으로 참가팀의 총 조회수 합이 적은 단위에게 💢벌칙릴스💢가 부과될 수 있습니다.\n\n📍릴스 고연전 참가 구글폼 링크: https://forms.gle/LHyiTRgsezZBerJy6\n\n| 제작 : 상경9반 기획정책국장 권혁우\n| 문의 : 기획국장 장여백, 학생회장 원준혁\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 10월 1주차 학운위 회의\n• 일시: 2026.10.01\n• 담당 국서: 학생회장단\n• 진행 상태: 완료",
