                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 2건)]\n\n??[공지 1] 2026.10.08 오후 1:07 쨌 복지국장 김동운\n----------------------------------------\n[2026학년도 2학기 D반 중간고사 간식행사]\n\n안녕하세요, 제18대 D반 학생회 Duet 복지국입니다.\n\n학우 여러분의 2학기 중간고사 응원을 위해 [D반 중간고사 간식행사]를 진행합니다! 많은 참여 부탁드립니다.\n\n학우분들을 대상으로 한 간식 수요조사 결과 서브웨이 샌드위치, 수제햄버거, 닭강정이 간식으로 선정되었습니다. 수요조사에 대한 많은 관심 감사드립니다~!\n\n간식행사 신청 구글폼: https://forms.gle/xYWHZZVXsZHLTtRN6\n\n🎁참여 방식 : 사전 신청 기간에 구글폼 \"선착순 신청\" 후, 반실에서 \"대면 수령\"\n🎁사전 신청 시간 : 26. 10. 09. (금) 17시~ (선착순 26명 마감)\n*17시 이전에 구글폼 제출 시 무효 처리되니, 꼭 17시 이후에 제출하시기 바랍니다.\n🎁실제 수령 시간 : 26. 10. 14. (수) 18시 ~ 18시 30분\n🎁실제 수령 장소 : 구법학관 D반 반실\n🎁메뉴 : 서브웨이 스파이시 쉬림프 샌드위치 + 칠성사이다제로 [10개] // 한솥도시락 닭강정 + 치킨마요 + 펩시제로라임 [8개] // 퍽앤어니언 어니언치즈버거 세트 (코카콜라 오리지널) [8개]\n\n❗학생회비 납부자만 신청 가능합니다.\n❗대면으로 본인이 수령함이 원칙입니다.\n❗명단 확정자(사전 신청자 가운데 선착순 26명)에 한하여 나눔합니다.\n❗메뉴 선택은 행사 당일 선착순으로  진행합니다.\n\n문의: 복지국장 김동운\n제작: 홍보국원 김선희\n\n??[공지 2] 2026.10.08 오후 4:19 쨌 기획/홍보국장 장여백\n----------------------------------------\n[2026-2학기 중간고사 스터디윗D]\n\n안녕하세요, Duet 기획국입니다.\n고연전이 끝나고 쌀쌀해진 날씨와 함께 벌써 2학기 중간고사가 한발 앞으로 다가왔습니다. 이에 맞춰 2026학년도 2학기 중간고사 스터디윗D를 시작하고자 합니다! 이번 중간고사도 다른 학우분들과 함께 서로 자극받으며 열심히 공부해보는 건 어떨까요?\n특히 이번 스터디윗D에는 학우 여러분들의 공부 열기를 더욱 불태우기 위해 지난 기말고사보다 한층 업그레이드된 경품들을 준비하였으니, 스터디윗D와 함께 열심히 공부하시고 경품과 함께 한층 좋은 성적도 얻어가셨으면 좋겠습니다:)\nD반 학우 여러분들의 많은 관심과 참여 부탁드립니다🔥\n\n📍열품타 초대링크  https://link.yeolpumta.com/P3R5cGU9Z3JvdXBJbnZpdGUmaWQ9NTgzNTE0OA==\n(비밀번호 : 2009)\n\n✅️ 행사 기간 : 10/12(월) - 10/21(수)\n\n✅️ 참여 방식\n1. 공유된 링크를 통해 \u0027열품타\u0027 앱 접속 후 닉네임을 이름+학번 뒤 3자리로 설정해주세요. (ex. 원준혁 088)\n2. 매일 공부를 시작할 때 타이머를 재생해주시고, 끝낼 때 타이머를 멈춰서 공부 시간을 체크해 주시면 됩니다.\n* 타이머를 실수로 끄지 않은 경우를 배제하기 위해 최대 집중 시간이 5시간을 초과한 날은 집계에서 제외합니다.\n** 출석 인증 미션은 없습니다! 사진 인증은 자유롭게 진행해 주시면 될 것 같습니다.\n\n✅ 참여 인정 기준\n총 10일의 기간 동안 \u00276일 이상 출석\u0027하고 \u0027총 공부시간 25시간 이상\u0027 인 학우만 행사 참여를 한 것으로 인정합니다.\n\n✅️ 경품 추첨\n경품 추첨은 참여 인정 기준을 달성한 학우분들에 한하여 진행합니다.\n*** 단, 참여 인정 기준을 달성한 학우 전원에게 참가 상품을 증정합니다.\n\n✅ 경품 목록\n- bhc 후라이드 + 콜라 기프티콘 (1명)\n- 배달의민족 1만원권 (1명) \n- 맥도날드 베토디 기프티콘 (2명)\n- 참가상품: 시험 스트레스를 날려버릴 수 있는 아이템🔥🍌\n\n| 제작 : 홍보국장 이윤주\n| 문의 : 기획국장 장여백, 학생회장 원준혁\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 26-2학기 스터디윗디 공지\n• 일시: 2026.10.08\n• 담당 국서: 기획국\n• 진행 상태: 완료",
