                               "noticeText":  "[📢 카카오톡 단체방 공식 공지 (총 3건)]\n\n??[공지 1] 2026.10.14 오후 1:05 쨌 복지국장 김동운\n----------------------------------------\n[D-Day 간식행사 배부 리마인드]\n\n안녕하세요, Duet 복지국입니다.\n\n금일 18시에 반실에서 간식 배부가 예정되어 있습니다. 사전에 공지한 명단 인원에 한하여 배부하며, 배부 시간 이후 남은 간식은 명단 관계 없이 선착순 배부 예정입니다.\n\n배부 시간: 18:00 ~ 18:30\n\n일정 참고하시어 꼭 받아가시길 바랍니다! 감사합니다:)\n\n??[공지 2] 2026.10.14 오후 6:27 쨌 복지국장 김동운\n----------------------------------------\n[26-2 중간고사 간식행사 잔여 간식 배부 안내]\n\n안녕하세요, Duet 복지국입니다.\n\n잔여 간식 18시 30분부터 배부 예정입니다!\n\n??[공지 3] 2026.10.14 오후 6:32 쨌 복지국장 김동운\n----------------------------------------\n간식행사 배부 마감입니다!\n\n많은 관심 감사합니다:)\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[노션(Notion) 캘린더 일정 기록]\n• 일정명: 26-2학기 간식행사\n• 일시: 2026.10.14\n• 담당 국서: 복지국\n• 진행 상태: 완료",
