                               "status":  "시작 전",
                               "title":  "제18-12차 D반 운영위원회 회의",
                               "summary":  "제18-10차 반운위(대학생RUN 제휴 거절), 제18-11차 새벽 긴급 반운위(릴스 고연전 및 타교생 회비 분리 원칙), 제9차 국장단회의, 제18-12차 반운위(학부 선관위 2인 파견)",
                               "images":  [
                                              "assets/images/monthly/m0708_1.png"
                                          ],
                               "noticeText":  "[📢 카카오톡 단체방 공식 공지]\n• 발신: 학생회장 원준혁 (2026.10.27 오후 1:20)\n----------------------------------------\n[연합mt 가수요조사 리마인드]\n가수요조사 리마인드 드립니다.\n원활한 행사 기획을 위해 참여하고자 하는 분들께서는 가수요조사 구글폼을 제출해주시면 감사하겠습니다!\n\n========================================\n[📋 노션(Notion) 캘린더 일정 기록 \u0026 회의 메모]\n[제18-10차 ~ 제18-12차 D반 운영위원회 및 9~10월 마무리 일정]\n• 9/8(화) 제18-10차 반운위: 외부 업체 \u00272026 대학생RUN\u0027 제휴 문의에 대해 반 단위가 아닌 학부 단위 사안으로 판단하여 제휴 반대(거절) 의결\n• 10/1(목) 02:00 제18-11차 긴급 반운위:\n  - 정기 고연전 전 연세대 에버나인과 진행할 신규 사업 \u0027릴스 고연전\u0027 긴급 인준 및 예산(약 5만 원, 엽떡 상품권) 승인\n  - 원칙: 우리 반 학생회비가 타교(연세대) 학생에게 지급되지 않도록 양교 개별 시상으로 분리하고, 양교 연합팀은 학생회비 미투입 특별상으로만 시상\n• 10/11(일) 제9차 국장단회의: 행정실 가구 요청 최종 확정, 퇴임사·공약 이행도·\u0027Duet 돌아보기\u0027 기획, 국서별 인수인계서 및 드라이브 아카이빙 마감\n• 10/27(화) 제18-12차 반운위: 자유전공학부 선거관리위원회 위원으로 김민정(24, 고학번대표), 채현찬(26, 신입생대표) 2인 파견 의결",
                               "thought":  "• 연세대 교류반과 \u0027릴스 고연전\u0027을 기획할 때 초기 연세대 측 가안에는 \u0027고대+연대 연합팀 촬영 시 조회수 10% 가산\u0027 조항이 있었으나, 새벽 2시 긴급 반운위(18-11차)에서 부학생회장과 신입생 대표가 \u0027연합팀이 일반 시상을 받으면 D반 학생회비가 연세대 학생 상품에 쓰이게 된다\u0027는 점을 정확히 짚어주었습니다. 덕분에 교내팀(학생회비 시상)과 연합팀(회비 미투입 특별상)을 깔끔하게 분리할 수 있었습니다.\n• 마지막으로 10월 말에는 「자유전공학부 선거시행세칙」 제152조에 따라 후보 등록 마감일 10일 전까지 반 운영위원회 의결을 거쳐 학부 선거관리위원회 위원 2명을 파견해야 하니 차기 회장단도 10월 중순~말 일정을 꼭 챙기시길 바랍니다!"
